        }
    }

    fn parse_object(&mut self) -> Result<ProofFields, String> {
        self.eat(b'{')?;
        let mut fields = ProofFields {
            tree_size: None,
            leaf_index: None,
            root: None,
            audit_path: None,
        };
        self.ws();

